function renderRecicList(sup){
  var el=document.getElementById('recList');if(!el)return;
  var st=(typeof window.recicGetState==='function')?window.recicGetState():{};
  var groups=Object.values(st||{}).sort(function(a,b){return (b.qtd-a.qtd)||(b.kg-a.kg);});
  if(!groups.length){el.innerHTML='<div class="empty"><div class="ei">'+(ICONS.layers||'')+'</div><b>Chão vazio</b><div class="es">Bipe uma etiqueta para começar a contar.</div></div>';return;}
  el.innerHTML=groups.map(function(g){
    var ets=_recEtList(g);
    var kgR=ets.reduce(function(s,x){return s+(Number(x.pl)||0);},0);
    return ''
    +'<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 18px;box-shadow:var(--sh-sm);margin-bottom:12px">'
    +'<div style="display:flex;align-items:flex-start;gap:14px;flex-wrap:wrap">'
      +'<div style="flex:1;min-width:200px">'
        +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span class="mono" style="font-weight:800;font-size:1.15rem">'+g.pr+'</span><span class="pill in">'+g.qtd+' bob</span></div>'
        +'<div style="color:var(--ink);font-size:.9rem;margin-top:6px;font-weight:500">'+(g.desc||'—')+'</div>'
        +'<div style="color:var(--faint);font-size:.72rem;margin-top:5px">último bipe '+rel(g.at)+'</div>'
      +'</div>'
      +'<div style="text-align:right;white-space:nowrap"><div style="font-family:var(--disp);font-weight:800;font-size:1.6rem;line-height:1">'+fmt(kgR)+' <span style="font-size:.8rem;color:var(--muted);font-weight:600">kg</span></div></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">'+ets.map(function(x){var adm=typeof isStrictAdmin==='function'&&isStrictAdmin();return '<span class="pill muted" '+(adm?'style="cursor:pointer" data-et="'+x.et+'" title="Tocar para remover esta etiqueta"':'')+'>'+x.et+(adm?' ✕':'')+'</span>';}).join('')+'</div>'
    +((typeof isStrictAdmin==='function'&&isStrictAdmin())?'<div style="display:flex;gap:10px;margin-top:12px"><button class="gbtn" data-rmcode="'+g.pr+'" style="margin-left:auto;color:var(--out)">Zerar código</button></div>':'')
    +'</div>';
  }).join('');
  el.querySelectorAll('[data-et]').forEach(function(b){b.onclick=function(){if(!(typeof isStrictAdmin==='function'&&isStrictAdmin()))return;try{if(typeof window.recicSaida==='function')window.recicSaida(b.dataset.et);}catch(e){}renderRecic();};});
  el.querySelectorAll('[data-rmcode]').forEach(function(b){b.onclick=function(){if(!(typeof isStrictAdmin==='function'&&isStrictAdmin()))return;try{if(typeof window.recicRemoveCode==='function')window.recicRemoveCode(b.dataset.rmcode);}catch(e){}renderRecic();};});
}
