// --- voz natural (pt-BR): escolhe a melhor voz disponível no aparelho e fala por frase (mais fluida) ---
var _vpVoice=null,_vpVoiceGot=false;
function vpPickBestVoice(voices){
  if(!voices||!voices.length)return null;
  var prefs=[/Google.*(português|Brasil|pt-BR)/i,/Microsoft.*(Francisca|Thalita).*(Online|Natural)/i,/Microsoft.*Maria.*(Online|Natural)/i,/Luciana/i,/Microsoft.*Francisca/i,/Microsoft.*Maria/i,/pt-BR/i,/^pt/i];
  for(var i=0;i<prefs.length;i++){
    var rx=prefs[i];
    var f=voices.find(function(v){return rx.test(v.name)||rx.test(v.lang);});
    if(f)return f;
  }
  return null;
}
function vpLoadVoice(){
  try{
    if(!window.speechSynthesis||_vpVoiceGot)return;
    function grab(){var vs=window.speechSynthesis.getVoices()||[];if(!vs.length)return;_vpVoice=vpPickBestVoice(vs);_vpVoiceGot=true;}
    grab();
    if(!_vpVoiceGot)window.speechSynthesis.onvoiceschanged=grab;
  }catch(e){}
}
vpLoadVoice();
function vpSplitSentences(text){return String(text||'').replace(/\s+/g,' ').trim().split(/(?<=[.!?;:])\s+(?=\S)/).filter(Boolean);}
function vpSpeakQueue(text,onDone,force){
  try{
    if(!window.speechSynthesis||!text){if(onDone)onDone();return;}
    if(!force&&!vpVoiceOn()){if(onDone)onDone();return;}
    vpLoadVoice();
    window.speechSynthesis.cancel();
    var parts=vpSplitSentences(text);
    if(!parts.length){if(onDone)onDone();return;}
    var i=0;
    function next(){
      if(i>=parts.length){if(onDone)onDone();return;}
      var chunk=parts[i++];
      var u=new SpeechSynthesisUtterance(chunk);
      u.lang='pt-BR';u.rate=0.98;u.pitch=1.02;u.volume=1;
      if(_vpVoice)u.voice=_vpVoice;
      var moved=false;
      function adv(){if(moved)return;moved=true;next();}
      u.onend=adv;u.onerror=adv;
      window.speechSynthesis.speak(u);
      setTimeout(adv,Math.max(2500,chunk.length*95));
    }
    next();
  }catch(e){if(onDone)onDone();}
}
function vpSpeak(text){vpSpeakQueue(text,null,false);}
function vpAddrSpeech(c){
  var parts=String(c||'').split('-');
  if(parts.length<2)return c||'';
  return 'rua '+parts[0]+', posição '+parts[1]+(parts[2]?(', nível '+parts[2]):'');
}
function vpBuildContext(){
  try{
    var wh=(cfg&&cfg.warehouse)||'70';
    var SS=(typeof S!=='undefined'&&Array.isArray(S))?S.filter(function(x){return x&&x.w===wh;}):[];
    var byPr={};
    SS.forEach(function(x){
      if(!x.o||!x.pr)return;
      if(!byPr[x.pr])byPr[x.pr]={produto:x.pr,descricao:(typeof boardDescOf==='function'?boardDescOf(x.pr):'')||'',peso_total_kg:0,enderecos:[]};
      byPr[x.pr].peso_total_kg+=(typeof pesoReal==='function'?pesoReal(x):(Number(x.q)||0));
      if(byPr[x.pr].enderecos.length<15)byPr[x.pr].enderecos.push(code(x)+' ('+Math.round((typeof pesoReal==='function'?pesoReal(x):(Number(x.q)||0)))+'kg)');
    });
    var produtos=Object.values(byPr).map(function(p){p.peso_total_kg=Math.round(p.peso_total_kg);return p;});
    var livres=SS.filter(function(x){return !x.o;});
    var livresPorRua={};
    livres.forEach(function(x){livresPorRua[x.s]=(livresPorRua[x.s]||0)+1;});
    var stg=(typeof STAGE!=='undefined'&&Array.isArray(STAGE))?STAGE:[];
    var floorState=(typeof window.floorGetState==='function')?window.floorGetState():{};
    var floorArr=Object.values(floorState||{});
    return {
      deposito:wh,
      total_posicoes:SS.length,
      posicoes_ocupadas:SS.length-livres.length,
      posicoes_livres:livres.length,
      livres_por_rua:livresPorRua,
      exemplos_enderecos_livres:livres.slice(0,25).map(function(x){return code(x);}),
      produtos:produtos.slice(0,180),
      estoque_intermediario_aguardando:stg.slice(0,60).map(function(s){return {produto:s.pr,peso_kg:s.pl,etiqueta:s.et};}),
      chao_bobinas_soltas:floorArr.slice(0,60).map(function(g){return {produto:g.pr,quantidade:g.qtd,peso_kg:g.kg};})
    };
  }catch(e){return {};}
}
function vpAskAI(question,history,_retry){
  var ctrl=(typeof AbortController!=='undefined')?new AbortController():null;
  var timer=setTimeout(function(){if(ctrl)ctrl.abort();},28000);
  return fetch('/wms-data/assistant',{
    method:'POST',
    headers:{'content-type':'application/json'},
    body:JSON.stringify({question:question,context:vpBuildContext(),history:Array.isArray(history)?history.slice(-10):[]}),
    signal:ctrl?ctrl.signal:undefined
  }).then(function(r){return r.json().catch(function(){return {};}).then(function(d){return {ok:r.ok,status:r.status,data:d};});}).then(function(res){
    clearTimeout(timer);
    if(!res.ok||!res.data||res.data.error||!res.data.answer){
      var e=new Error((res.data&&res.data.error)||('Erro na IA (HTTP '+res.status+')'));
      e.status=res.status;
      throw e;
    }
    return res.data.answer;
  }).catch(function(e){
    clearTimeout(timer);
    console.error('[Estoque Inteligente] falha ao perguntar'+(_retry?' (2ª tentativa)':'')+':',e);
    if(!_retry){
      return new Promise(function(res,rej){setTimeout(function(){vpAskAI(question,history,true).then(res).catch(rej);},900);});
    }
    throw e;
  });
}
function vpErrMsg(err){
  try{if(typeof navigator!=='undefined'&&navigator.onLine===false)return 'Sem internet — verifica a conexão e tenta de novo.';}catch(e){}
  if(err&&err.name==='AbortError')return 'O servidor demorou pra responder (timeout). Tenta de novo.';
  if(err instanceof TypeError)return 'Não consegui conectar no servidor (função /api/ask fora do ar?). Tenta de novo.';
  var st=err&&err.status;
  if(st===401||st===403)return 'Erro de autorização com a IA (HTTP '+st+') — chave de API inválida ou vencida.';
  if(st===404)return 'Endpoint da IA não encontrado (HTTP 404) — a função /api/ask pode não estar publicada.';
  if(st===429)return 'Limite de uso da IA atingido (HTTP 429) — tenta de novo em instantes.';
  if(st>=500)return 'Erro no servidor da IA (HTTP '+st+'): '+(err.message||'sem detalhes')+'.';
  if(err&&err.message)return 'Erro na IA: '+err.message;
  return 'Deu um erro aqui no servidor. Tenta de novo em instantes.';
}
