 $('#azDo').onclick=()=>{if(!chkEt()){toast('Bipe a bobina '+et+' para conferir',false);$('#azEt').click();return;}const c=norm($('#azLoc').value);if(!c){toast('Bipe o endereço',false);$('#azLoc').click();return;}if(placeBobina(et,it.pr,it.pl,c)){STAGE=STAGE.filter(s=>s.et!==et);saveStage();if(typeof syncDelStage==='function')syncDelStage(et);closeDrawer();renderRecv();/* re-renderiza o MAPA na hora, senão a vaga fica verde até salvar manual */try{if(typeof renderBoard==='function')renderBoard();}catch(e){}try{var _av=document.querySelector('.view.active');if(_av&&_av.id!=='v-recv'&&typeof render==='function')render(_av.id);}catch(e){}updateStageBadge();toast('Armazenado: '+et+' em '+c);vpSpeak('Armazenado com sucesso em '+vpAddrSpeech(c)+'.');}};
 [['azEt',{enter:false,title:'Conferir bobina'}],['azLoc',{enter:false,title:'Escanear endereço',scanKind:'addr'}]].forEach(function(p){var id=p[0],o=p[1];var el=$('#'+id);if(!el)return;if(window.addCam)addCam(id,o);scanLock(el);});
