  const navRecv=[...document.querySelectorAll('.nav')].find(n=>n.dataset.view==='v-recv');
  if(navRecv){const nv=document.createElement('div');nv.className='nav';nv.dataset.view='v-floor';nv.dataset.ic='layers';nv.innerHTML='<span class="ni"></span>Expedição - 71';navRecv.parentNode.insertBefore(nv,navRecv.nextSibling);nv.onclick=()=>go('v-floor');}
  const sec=document.createElement('section');sec.className='view';sec.id='v-floor';document.querySelector('main').appendChild(sec);
  TITLES['v-floor']='Expedição - 71';
