/* Senhas nunca sao exibidas no cadastro e novas senhas sao protegidas antes de salvar. */
(function(){
 var abrirUsuario=editUser;
 editUser=function(i){
  abrirUsuario(i);
  var campo=document.getElementById('uP'),salvar=document.getElementById('uSave');
  if(!campo||!salvar)return;
  var senhaAtual=(i!=null&&US[i])?US[i].p:'';
  campo.type='password';campo.value='';campo.autocomplete='new-password';
  campo.placeholder=i!=null?'Deixe vazio para manter a senha':'Crie uma senha segura';
  var salvarOriginal=salvar.onclick;
  salvar.onclick=async function(e){
   var digitada=campo.value;
   if(i==null&&!digitada){toast('Informe a senha do novo usuario',false);return;}
   try{
    var protegida=digitada?await WMSSecurity.protect(digitada):senhaAtual;
    campo.value=protegida;
    return await salvarOriginal.call(this,e);
   }
   catch(err){toast('Nao foi possivel proteger a senha neste navegador',false);}
   finally{if(campo&&campo.isConnected)campo.value='';}
  };
 };
 window.editUser=editUser;
})();

